    background: 'none',
    border: '0.5px solid #F5C51840',
    color: '#F5C518',
    fontSize: 10,
    fontFamily: "'DM Mono',monospace",
    padding: '3px 8px',
    borderRadius: 6,
    cursor: 'pointer',
    flexShrink: 0
  },
  deleteUserBtn: {
    background: 'none',
    border: '0.5px solid #e24b4a40',
    color: '#e24b4a',
    fontSize: 10,
    fontFamily: "'DM Mono',monospace",
    padding: '3px 8px',
