import React, { useEffect, useState } from 'react'
import { getAllClients, getClientsByStatus, createClient, updateClientStatus, getUsersForClient, addUser } from '../lib/clients'
import { issueAccessCode, getActiveCodesForClient, revokeAccessCode } from '../lib/accessCodes'
import { dispatchAccessCode } from '../lib/notifications'
import { supabase } from '../lib/supabase'

export default function AdminDashboard() {
  const [tab, setTab] = useState('overview')
  const [clients, setClients] = useState([])
  const [pendingClients, setPendingClients] = useState([])
  const [outreachClients, setOutreachClients] = useState([])
  const [selectedClient, setSelectedClient] = useState(null)
  const [clientUsers, setClientUsers] = useState([])
  const [activeCodes, setActiveCodes] = useState([])
  const [selectedUsers, setSelectedUsers] = useState([])
  const [userPerms, setUserPerms] = useState({})
  const [expireTime, setExpireTime] = useState('23:00')
  const [dispatching, setDispatching] = useState(false)
  const [dispatchResult, setDispatchResult] = useState([])
  const [showAddClient, setShowAddClient] = useState(false)
  const [showClientPanel, setShowClientPanel] = useState(false)
  const [panelClient, setPanelClient] = useState(null)
  const [panelUsers, setPanelUsers] = useState([])
  const [showAddUser, setShowAddUser] = useState(false)
  const [editingUser, setEditingUser] = useState(null)
  const [editingUsername, setEditingUsername] = useState(false)
  const [newUsername, setNewUsername] = useState('')
  const [editUser, setEditUser] = useState({ fullName:'', contact:'' })
  const [newUser, setNewUser] = useState({ fullName:'', contact:'' })
  const [newClient, setNewClient] = useState({ username:'', fullName:'', email:'', phone:'', submittedBy:'' })
  const [saving, setSaving] = useState(false)

  const [accessRequests, setAccessRequests] = useState([])

  useEffect(() => { loadAll(); loadRequests() }, [])

  async function loadRequests() {
    const { data } = await supabase
      .from('audit_log')
      .select('*')
      .eq('event_type', 'access_request')
      .order('created_at', { ascending: false })
      .limit(50)
    setAccessRequests(data || [])
  }

  async function loadAll() {
    const [all, pending, outreach] = await Promise.all([
      getClientsByStatus('active'),
      getClientsByStatus('pending'),
      getClientsByStatus('outreach')
    ])
    setClients(all); setPendingClients(pending); setOutreachClients(outreach)
  }

  async function openClientPanel(client) {
    setPanelClient(client); setShowClientPanel(true)
    setShowAddUser(false); setEditingUser(null)
    setNewUser({ fullName:'', contact:'' })
    const users = await getUsersForClient(client.id)
    setPanelUsers(users)
  }

  async function handleAddUser() {
    if (!newUser.fullName || !newUser.contact) return
    setSaving(true)
    try {
      await addUser({ clientId: panelClient.id, fullName: newUser.fullName, contact: newUser.contact, contactType: 'email' })
      const users = await getUsersForClient(panelClient.id)
      setPanelUsers(users); setShowAddUser(false); setNewUser({ fullName:'', contact:'' })
    } catch(e) { console.error(e) }
    setSaving(false)
  }

  async function handleEditUser() {
    if (!editUser.fullName || !editUser.contact) return
    setSaving(true)
    try {
      await supabase.from('users').update({ full_name: editUser.fullName, contact: editUser.contact, contact_type: 'email' }).eq('id', editingUser)
      const users = await getUsersForClient(panelClient.id)
      setPanelUsers(users); setEditingUser(null)
    } catch(e) { console.error(e) }
    setSaving(false)
  }

  async function handleDeleteUser(userId) {
    if (!window.confirm('Remove this user?')) return
    try {
      await supabase.from('users').update({ is_active: false }).eq('id', userId)
      setPanelUsers(prev => prev.filter(u => u.id !== userId))
    } catch(e) { console.error(e) }
  }

  async function handleChangeUsername() {
    if (!newUsername || !panelClient) return
    setSaving(true)
    const oldUsername = panelClient.username
    const cleanNew = newUsername.toLowerCase().replace(/\s/g, '')
    try {
      // Update client username
      await supabase.from('clients').update({ username: cleanNew }).eq('id', panelClient.id)
      // Update all convo_keys that contain old username — non destructive
      const { data: convos } = await supabase.from('conversations').select('id, convo_key').ilike('convo_key', `%${oldUsername}%`)
      for (const convo of convos || []) {
        const newKey = convo.convo_key.split('::').map(p => p === oldUsername ? cleanNew : p).sort().join('::')
        await supabase.from('conversations').update({ convo_key: newKey, contact_username: newKey }).eq('id', convo.id)
      }
      setPanelClient(p => ({...p, username: cleanNew}))
      setEditingUsername(false)
      setNewUsername('')
      loadAll()
    } catch(e) { console.error(e) }
    setSaving(false)
  }

  async function handleRevokeClientAccess(userId) {
    if (!window.confirm('Revoke this user\'s access to all active codes for this client immediately?')) return
    try {
      await supabase.from('access_codes').update({ is_active: false, revoked_at: new Date().toISOString(), revoked_reason: 'Admin revoked client access' })
        .eq('user_id', userId).eq('client_id', panelClient.id).eq('is_active', true)
      // Refresh codes
      const codes = await getActiveCodesForClient(panelClient.id)
      setActiveCodes(codes)
      alert('Access revoked immediately.')
    } catch(e) { console.error(e) }
  }

  async function selectClient(client) {
    setSelectedClient(client); setSelectedUsers([]); setDispatchResult([])
    const [users, codes] = await Promise.all([getUsersForClient(client.id), getActiveCodesForClient(client.id)])
    setClientUsers(users); setActiveCodes(codes)
    const perms = {}; users.forEach(u => perms[u.id] = 'read_send'); setUserPerms(perms)
  }

  function toggleUser(userId) {
    setSelectedUsers(prev => prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId])
  }

  async function generateAndDispatch() {
    if (!selectedClient || selectedUsers.length === 0) return
    setDispatching(true); setDispatchResult([])
    const today = new Date()
    const [h, m] = expireTime.split(':')
    const expiresAt = new Date(today.getFullYear(), today.getMonth(), today.getDate(), parseInt(h), parseInt(m))
    const results = []
    for (const userId of selectedUsers) {
      const user = clientUsers.find(u => u.id === userId)
      const permission = userPerms[userId] || 'read_send'
      try {
        const { code } = await issueAccessCode({ userId, clientId: selectedClient.id, permission, expiresAt: expiresAt.toISOString() })
        await new Promise(r => setTimeout(r, 1500))
        await dispatchAccessCode({ user, code, clientUsername: selectedClient.username, permission, expiresAt: expiresAt.toISOString() })
        results.push({ user, code, permission, status:'sent' })
      } catch(e) { results.push({ user, code:'—', permission, status:'failed', error: e.message }) }
    }
    setDispatchResult(results); setSelectedUsers([]); setDispatching(false)
    const codes = await getActiveCodesForClient(selectedClient.id)
    setActiveCodes(codes)
  }

  async function handleRevoke(codeId) {
    await revokeAccessCode(codeId, 'Revoked by admin')
    setActiveCodes(prev => prev.filter(c => c.id !== codeId))
  }

  async function handleAddClient() {
    if (!newClient.username || !newClient.fullName) return
    setSaving(true)
    try {
      await createClient(newClient); setShowAddClient(false)
      setNewClient({ username:'', fullName:'', email:'', phone:'', submittedBy:'' }); loadAll()
    } catch(e) { console.error(e) }
    setSaving(false)
  }

  async function advanceStatus(clientId, newStatus) {
    await updateClientStatus(clientId, newStatus); loadAll()
  }

  const permLabel = { read_send:'read + send', read_only:'read only', send_only:'send only' }
  const tabs = ['overview','pipeline','clients','codes','requests']
  const initials = (str) => str ? str.slice(0,2).toUpperCase() : '??'
  const neu = {
    card: '6px 6px 14px #12141c, -3px -3px 8px #252528',
    sm: '4px 4px 8px #12141c, -2px -2px 6px #252528',
  }

  return (
    <div style={s.dash}>

      {/* CLIENT DETAIL PANEL */}
      {showClientPanel && panelClient && (
        <div style={s.overlay} onClick={() => setShowClientPanel(false)}>
          <div style={s.slidePanel} onClick={e => e.stopPropagation()}>
            <div style={s.panelHead}>
              <div style={{ flex:1 }}>
                {editingUsername ? (
                  <div style={{ display:'flex', gap:8, alignItems:'center' }}>
                    <input style={{ ...s.formInput, margin:0, flex:1, fontSize:14 }} placeholder="new username" value={newUsername} onChange={e => setNewUsername(e.target.value.toLowerCase().replace(/\s/g,''))} autoFocus />
                    <button style={{ ...s.addBtn, padding:'6px 12px', boxShadow: neu.sm }} onClick={handleChangeUsername} disabled={saving}>{saving ? '...' : 'save'}</button>
                    <button style={s.ghostBtn} onClick={() => { setEditingUsername(false); setNewUsername('') }}>✕</button>
                  </div>
                ) : (
                  <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                    <div style={s.panelTitle}>@{panelClient.username}</div>
                    <button style={{ ...s.editUserBtn, fontSize:9 }} onClick={() => { setEditingUsername(true); setNewUsername(panelClient.username) }}>edit username</button>
                  </div>
                )}
                <div style={s.panelSub}>{panelClient.full_name}</div>
              </div>
              <button style={s.closeBtn} onClick={() => setShowClientPanel(false)}>✕</button>
            </div>

            <div style={s.panelBody}>
              <div style={s.panelSecHead}>
                <span style={s.secLabel}>users</span>
                <button style={{ ...s.addBtn, boxShadow: neu.sm }} onClick={() => setShowAddUser(v => !v)}>+ add user</button>
              </div>

              {showAddUser && (
                <div style={{ ...s.formCard, boxShadow: neu.sm }}>
                  <div style={s.formLabel}>full name</div>
                  <input style={s.formInput} placeholder="e.g. Marcus T." value={newUser.fullName} onChange={e => setNewUser(p => ({...p, fullName: e.target.value}))} />
                  <div style={s.formLabel}>email address</div>
                  <input style={s.formInput} type="email" placeholder="email@example.com" value={newUser.contact} onChange={e => setNewUser(p => ({...p, contact: e.target.value}))} />
                  <div style={{ display:'flex', gap:8, marginTop:10 }}>
                    <button style={{ ...s.addBtn, padding:'8px 16px', boxShadow: neu.sm }} onClick={handleAddUser} disabled={saving}>{saving ? 'saving...' : 'save user'}</button>
                    <button style={{ ...s.ghostBtn }} onClick={() => setShowAddUser(false)}>cancel</button>
                  </div>
                </div>
              )}

              {panelUsers.length === 0 && !showAddUser && (
                <div style={s.emptyState}>no users yet — add one above</div>
              )}

              {panelUsers.map(user => (
                <div key={user.id} style={{ ...s.userCard, boxShadow: neu.sm }}>
                  {editingUser === user.id ? (
                    <div style={{ width:'100%' }}>
                      <div style={s.formLabel}>full name</div>
                      <input style={s.formInput} value={editUser.fullName} onChange={e => setEditUser(p => ({...p, fullName: e.target.value}))} />
                      <div style={s.formLabel}>email address</div>
                      <input style={s.formInput} type="email" value={editUser.contact} onChange={e => setEditUser(p => ({...p, contact: e.target.value}))} />
                      <div style={{ display:'flex', gap:8, marginTop:10 }}>
                        <button style={{ ...s.addBtn, padding:'6px 14px', boxShadow: neu.sm }} onClick={handleEditUser} disabled={saving}>{saving ? 'saving...' : 'save'}</button>
                        <button style={s.ghostBtn} onClick={() => setEditingUser(null)}>cancel</button>
                      </div>
                    </div>
                  ) : (
                    <div style={{ display:'flex', alignItems:'center', gap:10, width:'100%' }}>
                      <div style={s.userAvatar}>{initials(user.full_name)}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={s.userName}>{user.full_name}</div>
                        <div style={s.userContact}>✉ {user.contact}</div>
                      </div>
                      <button style={s.editUserBtn} onClick={() => { setEditingUser(user.id); setEditUser({ fullName: user.full_name, contact: user.contact }) }}>edit</button>
                      <button style={{ ...s.deleteUserBtn, borderColor:'#e8a02040', color:'#e8a020' }} onClick={() => handleRevokeClientAccess(user.id)}>revoke</button>
                      <button style={s.deleteUserBtn} onClick={() => handleDeleteUser(user.id)}>remove</button>
                    </div>
                  )}
                </div>
              ))}
            </div>

            <div style={{ padding:'0 20px 24px' }}>
              <button style={{ ...s.addBtn, width:'100%', padding:13, fontSize:14, boxShadow: neu.sm }}
                onClick={() => { setShowClientPanel(false); setTab('codes'); selectClient(panelClient) }}>
                go to code generation →
              </button>
            </div>
          </div>
        </div>
      )}

      {/* TOPBAR */}
      <div style={s.topbar}>
        <div style={s.topLeft}>
          <svg width="30" height="30" viewBox="0 0 36 36" fill="none">
            <rect width="36" height="36" rx="10" fill="#1a1a1e"/>
            <path d="M8 12C8 10.3431 9.34315 9 11 9H25C26.6569 9 28 10.3431 28 12V20C28 21.6569 26.6569 23 25 23H20L15 27V23H11C9.34315 23 8 21.6569 8 20V12Z" fill="#F5C518"/>
          </svg>
          <span style={s.appTitle}>BANQO</span>
          <span style={s.adminBadge}>super admin</span>
        </div>
        <span style={s.dateLabel}>{new Date().toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric' })}</span>
      </div>

      {/* NAV TABS */}
      <div style={s.navTabs}>
        {tabs.map(t => (
          <div key={t} style={{ ...s.ntab, ...(tab === t ? s.ntabActive : {}) }} onClick={() => setTab(t)}>
            {t}
            {t === 'pipeline' && (pendingClients.length + outreachClients.length) > 0 && (
              <span style={s.tabBadge}>{pendingClients.length + outreachClients.length}</span>
            )}
          </div>
        ))}
      </div>

      <div style={s.content}>

        {/* OVERVIEW */}
        {tab === 'overview' && (
          <>
            <div style={s.statsRow}>
              {[
                { label:'active clients', val: clients.length, sub:'total' },
                { label:'pending', val: pendingClients.length + outreachClients.length, sub:'needs attention', warn: true },
                { label:'active codes', val: activeCodes.length, sub:'today' },
                { label:'messages', val: 0, sub:'today' },
              ].map(stat => (
                <div key={stat.label} style={{ ...s.statCard, boxShadow: neu.card }}>
                  <div style={s.statLabel}>{stat.label}</div>
                  <div style={s.statVal}>{stat.val}</div>
                  <div style={{ ...s.statSub, color: stat.warn ? '#e8a020' : '#F5C518' }}>{stat.sub}</div>
                </div>
              ))}
            </div>

            {pendingClients.length > 0 && (
              <div style={{ ...s.panel, boxShadow: neu.card }}>
                <div style={s.panelTitle2}>needs attention</div>
                {pendingClients.map(c => (
                  <div key={c.id} style={{ ...s.clientRow, borderColor:'#e8a020' }}>
                    <div style={{ ...s.clAv, background:'#2a1f05', color:'#F5C518' }}>{initials(c.full_name)}</div>
                    <div style={s.clInfo}>
                      <div style={s.clHandle}>{c.full_name}</div>
                      <div style={s.clSub}>@{c.username} · submitted by {c.submitted_by}</div>
                      <div style={{ color:'#e8a020', fontSize:11, fontFamily:"'DM Mono',monospace" }}>pending outreach</div>
                    </div>
                    <button style={{ ...s.advBtn, boxShadow: neu.sm }} onClick={() => advanceStatus(c.id, 'outreach')}>outreach made →</button>
                  </div>
                ))}
              </div>
            )}

            <div style={{ ...s.panel, boxShadow: neu.card }}>
              <div style={s.panelTitle2}>active clients</div>
              {clients.length === 0 && <div style={s.emptyState}>no active clients yet</div>}
              {clients.map(c => (
                <div key={c.id} style={s.clientRow} onClick={() => openClientPanel(c)}>
                  <div style={{ ...s.clAv, background:'#2a1f05', color:'#F5C518' }}>{initials(c.username)}</div>
                  <div style={s.clInfo}>
                    <div style={s.clHandle}>@{c.username}</div>
                    <div style={s.clSub}>{c.full_name}</div>
                  </div>
                  <span style={s.manageLink}>manage →</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* PIPELINE */}
        {tab === 'pipeline' && (
          <>
            <div style={s.secHead}>
              <span style={s.secLabel}>client onboarding pipeline</span>
              <button style={{ ...s.addBtn, boxShadow: neu.sm }} onClick={() => setShowAddClient(v => !v)}>+ add client</button>
            </div>

            {showAddClient && (
              <div style={{ ...s.panel, boxShadow: neu.card }}>
                <div style={s.panelTitle2}>new client</div>
                {[['Username (no spaces)','username'],['Full Name','fullName'],['Email','email'],['Phone','phone'],['Submitted By','submittedBy']].map(([label,key]) => (
                  <div key={key} style={{ marginBottom:10 }}>
                    <div style={s.formLabel}>{label}</div>
                    <input style={s.formInput} value={newClient[key]} onChange={e => setNewClient(p => ({...p,[key]:e.target.value}))} />
                  </div>
                ))}
                <div style={{ display:'flex', gap:8, marginTop:4 }}>
                  <button style={{ ...s.addBtn, boxShadow: neu.sm }} onClick={handleAddClient} disabled={saving}>{saving ? 'saving...' : 'save client'}</button>
                  <button style={s.ghostBtn} onClick={() => setShowAddClient(false)}>cancel</button>
                </div>
              </div>
            )}

            <div style={s.pipeline}>
              {[
                { label:'pending', color:'#e8a020', items: pendingClients, action:'outreach made →', nextStatus:'outreach' },
                { label:'outreach', color:'#85b7eb', items: outreachClients, action:'activate →', nextStatus:'active' },
                { label:'activated', color:'#F5C518', items: clients, action:null }
              ].map(col => (
                <div key={col.label} style={{ ...s.pipeCol, boxShadow: neu.card }}>
                  <div style={s.pipeColHead}>
                    <span style={{ ...s.pipeColTitle, color: col.color }}>{col.label}</span>
                    <span style={s.pipeCount}>{col.items.length}</span>
                  </div>
                  {col.items.length === 0 && <div style={s.pipeEmpty}>empty</div>}
                  {col.items.map(c => (
                    <div key={c.id} style={{ ...s.pipeCard, boxShadow: neu.sm }}>
                      <div style={s.pipeCardName}>{c.full_name}</div>
                      <div style={s.pipeCardSub}>@{c.username}</div>
                      {c.submitted_by && <div style={s.submittedBy}>by {c.submitted_by}</div>}
                      {col.action && (
                        <button style={{ ...s.pipeAction, background: col.nextStatus === 'active' ? '#F5C518' : '#1a1a1e', color: col.nextStatus === 'active' ? '#111114' : col.color, border: `0.5px solid ${col.color}40` }}
                          onClick={() => advanceStatus(c.id, col.nextStatus)}>
                          {col.action}
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </>
        )}

        {/* CLIENTS */}
        {tab === 'clients' && (
          <>
            <div style={s.secHead}>
              <span style={s.secLabel}>active clients ({clients.length})</span>
              <button style={{ ...s.addBtn, boxShadow: neu.sm }} onClick={() => { setShowAddClient(true); setTab('pipeline') }}>+ add client</button>
            </div>
            {clients.length === 0 && <div style={s.emptyState}>no active clients — add via pipeline tab</div>}
            {clients.map(c => (
              <div key={c.id} style={{ ...s.clientRow, boxShadow: neu.card, marginBottom:10 }} onClick={() => openClientPanel(c)}>
                <div style={{ ...s.clAv, background:'#2a1f05', color:'#F5C518' }}>{initials(c.username)}</div>
                <div style={s.clInfo}>
                  <div style={s.clHandle}>@{c.username}</div>
                  <div style={s.clSub}>{c.full_name}</div>
                </div>
                <span style={s.manageLink}>manage →</span>
              </div>
            ))}
          </>
        )}

        {/* CODES */}
        {tab === 'codes' && (
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16 }}>
            <div style={{ ...s.panel, boxShadow: neu.card }}>
              <div style={s.panelTitle2}>step 1 · select client</div>
              <div style={{ display:'flex', flexWrap:'wrap', gap:8, marginBottom:16 }}>
                {clients.map(c => (
                  <div key={c.id}
                    style={{ ...s.chip, boxShadow: neu.sm, ...(selectedClient?.id === c.id ? s.chipSelected : {}) }}
                    onClick={() => selectClient(c)}>
                    @{c.username}
                  </div>
                ))}
              </div>

              {selectedClient && (
                <>
                  <div style={s.panelTitle2}>step 2 · select users</div>
                  {clientUsers.length === 0 && (
                    <div style={s.emptyState}>no users for this client —
                      <span style={{ color:'#F5C518', cursor:'pointer' }} onClick={() => { setTab('clients'); openClientPanel(selectedClient) }}> add users first</span>
                    </div>
                  )}
                  <div style={{ display:'flex', justifyContent:'space-between', marginBottom:8 }}>
                    {clientUsers.length > 0 && <button style={s.selAllBtn} onClick={() => setSelectedUsers(clientUsers.map(u => u.id))}>select all</button>}
                    <span style={{ fontSize:11, fontFamily:"'DM Mono',monospace", color:'#888aa0' }}>{selectedUsers.length} selected</span>
                  </div>
                  {clientUsers.map(user => (
                    <div key={user.id}
                      style={{ ...s.userRow, boxShadow: neu.sm, ...(selectedUsers.includes(user.id) ? s.userRowChecked : {}) }}
                      onClick={() => toggleUser(user.id)}>
                      <div style={{ ...s.checkBox, ...(selectedUsers.includes(user.id) ? s.checkBoxChecked : {}) }}>
                        {selectedUsers.includes(user.id) && '✓'}
                      </div>
                      <div style={{ flex:1 }}>
                        <div style={{ fontSize:13, fontWeight:600, color:'#ffffff' }}>{user.full_name}</div>
                        <div style={{ fontSize:11, fontFamily:"'DM Mono',monospace", color:'#888aa0' }}>✉ {user.contact}</div>
                      </div>
                      {selectedUsers.includes(user.id) && (
                        <select style={s.permSelect} value={userPerms[user.id]} onChange={e => setUserPerms(p => ({...p,[user.id]:e.target.value}))} onClick={e => e.stopPropagation()}>
                          <option value="read_send">read + send</option>
                          <option value="read_only">read only</option>
                          <option value="send_only">send only</option>
                        </select>
                      )}
                    </div>
                  ))}

                  {clientUsers.length > 0 && (
                    <>
                      <div style={{ ...s.panelTitle2, marginTop:14 }}>step 3 · expiry time</div>
                      <select style={s.formInput} value={expireTime} onChange={e => setExpireTime(e.target.value)}>
                        <option value="18:00">6:00 PM ET</option>
                        <option value="20:00">8:00 PM ET</option>
                        <option value="23:00">11:00 PM ET</option>
                        <option value="23:59">midnight ET</option>
                      </select>
                      <button
                        style={{ ...s.addBtn, width:'100%', marginTop:12, padding:12, opacity: selectedUsers.length === 0 || dispatching ? 0.4 : 1, boxShadow: neu.sm }}
                        disabled={selectedUsers.length === 0 || dispatching}
                        onClick={generateAndDispatch}>
                        {dispatching ? 'dispatching...' : `generate & send to ${selectedUsers.length} user${selectedUsers.length !== 1 ? 's' : ''}`}
                      </button>
                    </>
                  )}

                  {dispatchResult.length > 0 && (
                    <div style={{ marginTop:12, background:'#1e1c0a', border:'0.5px solid #F5C51840', borderRadius:12, padding:14 }}>
                      <div style={{ fontSize:12, fontFamily:"'DM Mono',monospace", color:'#F5C518', marginBottom:10 }}>✓ codes dispatched</div>
                      {dispatchResult.map((r,i) => (
                        <div key={i} style={{ display:'flex', alignItems:'center', gap:8, padding:'7px 0', borderBottom:'0.5px solid #2a1f05' }}>
                          <span style={{ flex:1, fontSize:12, fontWeight:600, color:'#ffffff' }}>{r.user.full_name}</span>
                          <span style={{ fontSize:18, fontFamily:"'DM Mono',monospace", color:'#F5C518', letterSpacing:'0.2em' }}>{r.code}</span>
                          <span style={{ color: r.status === 'sent' ? '#F5C518' : '#e24b4a', fontSize:14 }}>{r.status === 'sent' ? '✓' : '✗'}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </>
              )}
            </div>

            <div style={{ ...s.panel, boxShadow: neu.card }}>
              <div style={s.panelTitle2}>active codes today {selectedClient ? `· @${selectedClient.username}` : ''}</div>
              {activeCodes.length === 0 && <div style={s.emptyState}>no active codes</div>}
              {activeCodes.map(c => (
                <div key={c.id} style={{ ...s.codeItem, boxShadow: neu.sm }}>
                  <div style={{ flex:1 }}>
                    <div style={{ fontSize:13, fontWeight:600, color:'#ffffff' }}>{c.users?.full_name}</div>
                    <div style={{ fontSize:11, fontFamily:"'DM Mono',monospace", color:'#888aa0' }}>
                      {permLabel[c.permission]} · exp {new Date(c.expires_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}
                    </div>
                  </div>
                  <div style={{ fontSize:20, fontFamily:"'DM Mono',monospace", color:'#F5C518', letterSpacing:'0.2em' }}>{c.code}</div>
                  <button style={s.revokeBtn} onClick={() => handleRevoke(c.id)}>revoke</button>
                </div>
              ))}
            </div>
          </div>
        )}
        {/* REQUESTS */}
        {tab === 'requests' && (
          <>
            <div style={s.secHead}>
              <span style={s.secLabel}>access requests ({accessRequests.length})</span>
              <button style={{ ...s.addBtn, boxShadow: neu.sm }} onClick={loadRequests}>refresh</button>
            </div>
            {accessRequests.length === 0 && <div style={s.emptyState}>no access requests yet</div>}
            {accessRequests.map(req => (
              <div key={req.id} style={{ ...s.clientRow, boxShadow: neu.card, marginBottom:10, flexDirection:'column', alignItems:'flex-start', gap:8 }}>
                <div style={{ display:'flex', alignItems:'center', gap:12, width:'100%' }}>
                  <div style={{ ...s.clAv, background:'#2a1f05', color:'#F5C518' }}>{(req.meta?.first_name || '?').slice(0,2).toUpperCase()}</div>
                  <div style={s.clInfo}>
                    <div style={s.clHandle}>{req.meta?.first_name} → @{req.meta?.client_username}</div>
                    <div style={s.clSub}>{new Date(req.created_at).toLocaleString()}</div>
                  </div>
                  <span style={{ ...s.manageLink, marginLeft:'auto', color:'#e8a020' }}>pending</span>
                </div>
                {req.meta?.note && (
                  <div style={{ background:'#111114', border:'0.5px solid #252528', borderRadius:8, padding:'10px 12px', width:'100%', fontSize:13, color:'#888aa0', fontFamily:"'DM Mono',monospace", lineHeight:1.5 }}>
                    "{req.meta.note}"
                  </div>
                )}
              </div>
            ))}
          </>
        )}

      </div>
    </div>
  )
}

